head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.trigger1_onclick = function(e) {
    imports("uiplugin.popup");
    WebSquare.util.openPopup("", { //get방식으로 팝업의 아이디를 넘김니다.
        id: "pop1",
        type: "litewindow",
        width: 500,
        height: 500,
        top: 50,
        left: 50,
        popupName: "test",
        modal: false,
        useIFrame: false,
        resizable: false,
        status: false,
        menubar: false,
        scrollbars: scroll,
        title: 'test222',
        useMaxmimize: true,
        // 팝업 버튼 기능 사용
        useControl: true,
        // 기능별 버튼 사용 여부 최소/최대/닫기
        controls: {
            minimize: true,
            maximize: true,
            close: true
        },
        // 팝업 최소화 기능 사용 여부 false:최소화 미사용, true:최소화 사
        foldOnMinimized: true,
        //최소화 시 타이틀 width size
        foldSize: {
            width: 100
        }
    });
};
scwin.isPopupOutUI = function() {
    var el = (document.getElementById('pop1') || document.getElementById('mf_pop1'));
    var elStyle = window.getComputedStyle(el);
    return scwin.getPositionP(el.style.top, elStyle) > scwin.parse(containerStyle.getPropertyValue("height"));
}
scwin.getPositionP = function(posiP, styleP) {
    return scwin.parse(posiP) + scwin.parse(styleP.getPropertyValue("height")) - scwin.parse(styleP.getPropertyValue("border-width")) * 2;
}
scwin.parse = function(style) {
    //return parseInt(style.replace("px", ""));
    return 1*(style.replace("px", ""));
}
scwin.position = function(styleC, styleP) {
    return scwin.parse(styleC) - scwin.parse(styleP) + "px";
}
scwin.movePopToBottom = function() {
    var el = (document.getElementById('pop1') || document.getElementById('mf_pop1'));
    var elStyle = window.getComputedStyle(el);
    el.style.top = scwin.position(containerStyle.getPropertyValue("height"), elStyle.getPropertyValue("height"));
    el.style.left = scwin.position(containerStyle.getPropertyValue("width"), elStyle.getPropertyValue("width"));
    el.style.bottom = 0;
    el.style.right = 0;
}
scwin.checktype = function() {
    return typeof pop1;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Jan-2018
    window.containerStyle = window.getComputedStyle(scwin.__getDom($p.id + "wq_uuid_1"));
    //end unitTest
}
